    lines(x$decile, x$accuracy, type = "b", pch = 19, col = cols[(k - 1) %% length(cols) + 1])
  }
  legend("bottomleft", tabs, col = cols[(seq_along(tabs) - 1) %% length(cols) + 1], pch = 19,
         lty = 1, bty = "n", cex = 0.8)
}
